 const openTeam=()=>{closePanels();setObservationsOpen(true);setPartyOpen(true)};
 const logo=<div className="brand"><span className="brand-mark">N<span>✦</span></span><div>HOTEL <b>NEON</b><small>{t('DO NOT DISTURB THE EVIDENCE','証拠につき、お静かに')}</small></div></div>;
 if(!snap)return <main className="reception"><div className="hero-art"/><div className="hero-shade"/><header>{logo}<div className="language"><button className={locale==='en'?'selected':''} onClick={()=>setLocale('en')}>EN</button><button className={locale==='ja'?'selected':''} onClick={()=>setLocale('ja')}>日本語</button></div></header><section className="welcome-copy"><span className="eyebrow">AN ORIGINAL CO-OP MYSTERY</span><h1>{t('A holiday.','休暇のはずが、')}<br/>{t('A missing robot.','ロボット失踪事件。')}<br/><em>{t('Absolutely no work.','仕事は忘れる約束。')}</em></h1><p>{t('Find PIP. Follow the clues. Save your holiday.','PIPを探して、休暇を取り戻そう。')}</p><div className="amenities"><span>◇ {t('Five security puzzles','セキュリティパズル5問')}</span><span>⌁ {t('One shared investigation','ひとつの共同捜査')}</span><span>♨ {t('Hot spring pending','温泉は捜査の後で')}</span></div></section><section className="checkin"><div className="room-tag">WELCOME TO NEON</div><h2>{t('Choose your party.','仲間とチェックイン。')}</h2><div className="tabs"><button className={mode==='create'?'selected':''} onClick={()=>setMode('create')}>{t('Create a room','ルーム作成')}</button><button className={mode==='join'?'selected':''} onClick={()=>setMode('join')}>{t('Join friends','参加する')}</button></div><form onSubmit={e=>{e.preventDefault();void enter()}}><label className="field"><span>{t('Nickname','ニックネーム')}</span><input autoComplete="nickname" maxLength={30} value={name} onChange={e=>setName(e.target.value)} required placeholder={t('What should PIP call you?','PIPに呼んでほしい名前')}/></label>{mode==='join'&&<label className="field"><span>{t('Room code','ルームコード')}</span><input value={joinCode} onChange={e=>setJoinCode(e.target.value.toUpperCase())} maxLength={6} required placeholder="ABC234"/></label>}<button className="primary full" disabled={busy}>{busy?t('Connecting…','接続中…'):mode==='create'?t('Check in & create room →','チェックインして作成 →'):t('Join the investigation →','捜査に参加 →')}</button></form><p className="fine">{mode==='create'?t('1–7 players · English / 日本語 · No timer','1〜7人 · English / 日本語 · 時間制限なし'):t('The host chooses one language for the whole room.','言語はホストがルーム全体に設定します。')}</p>{error&&<p role="alert" className="error">{error}</p>}{resume&&<button className="full resume" onClick={()=>{revision.current=0;setSession(resume)}}>{t("Resume room ","ルームに戻る：")}{resume.code} ↗</button>}<span className="prototype">LOCAL PROTOTYPE · v0.15</span></section></main>;
